{
  "platform": "host",
  "provider": "Tool",
  "method": "listTools",
  "data": {
    "tools": [
      {
        "name": "cordis_inspect_list",
        "description": "List every Cordis Inspect Provider currently known to the Host, including local Host Providers and the latest manifests synchronized from the Client. Each entry includes its platform, purpose, read-only methods, and input/output schemas. Call this Tool before writing or configuring a plugin, then select the provider and method for cordis_inspect_query from its result. Do not guess names or treat an Inspect method as a business Service that Plugin code can call.",
        "parameters": {
          "type": "object",
          "properties": {}
        }
      },
      {
        "name": "cordis_inspect_query",
        "description": "Run a read-only query declared by an Inspect Provider. platform, provider, and method must come from cordis_inspect_list, and input must satisfy that method's schema. Use this Tool before writing plugin code to read exact Service methods, Event modes, plugin Config schemas, Tool schemas, theme tokens, or live Slot trees and props. Host queries run locally. A Client query waits for the first valid page response within the configured timeout; otherwise it reports a Client failure or asks you to reconnect and retry. This Tool cannot invoke business Service methods or modify the runtime.",
        "parameters": {
          "type": "object",
          "properties": {
            "platform": {
              "type": "string",
              "description": "Runtime platform that owns the Provider.",
              "enum": [
                "host",
                "client"
              ]
            },
            "provider": {
              "type": "string",
              "description": "Exact Provider ID returned by cordis_inspect_list."
            },
            "method": {
              "type": "string",
              "description": "Exact method name declared by the Provider manifest."
            },
            "input": {
              "description": "Optional query input; it must satisfy the method input schema."
            }
          },
          "required": [
            "platform",
            "provider",
            "method"
          ]
        }
      },
      {
        "name": "plugin_manager",
        "description": "List plugins or bundles in the current profile, enable or disable them, install a bundle, or remove an installed bundle. Every action requires danger-full-access permission or approval for this call. Approval does not change the session permission mode. Changes affect every session in this profile. List first to obtain exact identifiers. Package installation can execute allowed build scripts. Live profiles apply changes immediately; startup profiles require restart. Incompatible DSH peer dependencies block installation and activation. Version exemptions risk crashes and data loss: warn the user and obtain explicit permission for the exact plugin and runtime versions before granting one.",
        "parameters": {
          "type": "object",
          "properties": {
            "action": {
              "type": "string",
              "description": "Management operation.",
              "enum": [
                "list_plugins",
                "list_bundles",
                "set_plugin",
                "set_bundle",
                "install_bundle",
                "remove_bundle",
                "list_version_exemptions",
                "set_version_exemption"
              ]
            },
            "target": {
              "type": "string",
              "description": "Plugin entry id, bundle package name, or installation spec, according to action."
            },
            "enabled": {
              "type": "boolean",
              "description": "Required for set operations; defaults to true for installation. For set_version_exemption, true grants and false revokes."
            },
            "runtimeVersion": {
              "type": "string",
              "description": "For set_version_exemption: exact DSH version from list_version_exemptions. Target must be the manifest package-name@version, not an alias or version range."
            },
            "acceptRisk": {
              "type": "boolean",
              "description": "For granting an exemption: true only after warning the user about possible crashes and data loss and receiving explicit permission for this exact plugin/runtime pair. General installation permission is not enough."
            },
            "approvedBuilds": {
              "type": "array",
              "description": "For install_bundle: pass names from pendingBuilds only after the user explicitly approves running their install scripts in the conversation. This grants persistent permission for this profile.",
              "items": {
                "type": "string"
              }
            },
            "registry": {
              "type": "string",
              "description": "For install_bundle: the npm registry URL asked first, when the user names one; otherwise the configured registry is asked, and its configured fallbacks while a registry is unreachable."
            },
            "offset": {
              "type": "number",
              "description": "Zero-based list offset; defaults to 0."
            },
            "limit": {
              "type": "number",
              "description": "List page size, from 1 to 100; defaults to 25."
            }
          },
          "required": [
            "action"
          ]
        }
      }
    ]
  }
}

{
  "platform": "host",
  "provider": "Service",
  "method": "listService",
  "data": {
    "mode": "service",
    "service": {
      "key": "agents",
      "description": "Agent service (`ctx.agents`): tracks live agents and carries the initiating Agent through one process-local asynchronous driver chain. Agent *creation* is provided by whichever plugin implements the AgentFactory (`@deepseek-ai/dsh-agent-loop`), registered via setFactory.\n\nInitiator methods provide same-process causal attribution only. Ambient presence is neither liveness proof nor authorization; subjects and owners remain explicit, as does identity at worker, process, persistence, and wire boundaries. Returned Promise boundaries drain during teardown, except a nested lineage that starts an owning-fiber unload is excluded from its own drain.",
      "access": {
        "optional": {
          "expression": "ctx.get(\"agents\")",
          "requiresUndefinedCheck": true
        },
        "hardDependency": {
          "inject": [
            "agents"
          ],
          "expression": "ctx.agents"
        }
      },
      "methods": [
        {
          "signature": "currentInitiator(): Agent | undefined",
          "description": "Read the Agent that initiated the inherited asynchronous driver chain. Use this optional form for logging, tracing, metrics, or host attribution that also supports agentless calls. When a parent creates a child, setup reports the causal parent while the setup callback's Agent parameter identifies the child.",
          "parameters": [],
          "returns": "the inherited Agent, or `undefined` outside an initiator boundary and inside an explicit clearing boundary.",
          "throws": [
            "when this service instance has been disposed."
          ]
        },
        {
          "signature": "requireInitiator(): Agent",
          "description": "Read the initiating Agent and fail when no initiator boundary is active. Use this for private helpers contractually below a driver, or for a deployment-owned outbound request whose contract forbids agentless calls. Generic or direct-call paths use optional lookup or explicit request fields.",
          "parameters": [],
          "returns": "the inherited Agent.",
          "throws": [
            "when no initiator is active or this service instance has been disposed."
          ]
        },
        {
          "signature": "withInitiator<T>(agent: Agent, operation: () => T): T",
          "description": "Run an operation with one exact Agent as its process-local initiator. The exact synchronous value or Promise returned by the operation is preserved. Custom drivers and test harnesses wrap their complete returned foreground lifetime. A queue or wire receiver may establish this boundary only after validating explicit identity and resolving the exact live Agent; this method does neither. Detached work remains owned by the subsystem that starts it.",
          "parameters": [
            {
              "name": "agent",
              "description": "initiating Agent to inherit; presence is neither liveness proof nor authorization."
            },
            {
              "name": "operation",
              "description": "synchronous or asynchronous operation to invoke."
            }
          ],
          "returns": "the exact value returned by `operation`.",
          "throws": [
            "when the initiator scope is closing/disposed, or when `operation` throws."
          ]
        },
        {
          "signature": "withoutInitiator<T>(operation: () => T): T",
          "description": "Run an operation inside a boundary that hides any inherited initiating Agent. The exact synchronous value or Promise is preserved. Use this while creating lazy shared timers, queue pumps, pool maintenance, watchers, or exporters so they do not inherit the first Agent that happens to initialize them. It clears only initiator attribution, not explicit fields, and does not own or drain detached resources.",
          "parameters": [
            {
              "name": "operation",
              "description": "synchronous or asynchronous operation to invoke without an initiator."
            }
          ],
          "returns": "the exact value returned by `operation`.",
          "throws": [
            "when the initiator scope is closing/disposed, or when `operation` throws."
          ]
        },
        {
          "signature": "setFactory(factory: AgentFactory): () => void",
          "description": "Register the agent-creation factory (the loop calls this on construction, effect-scoped). A traced Cordis service is canonicalized to its concrete target; each create/resume call is then traced through that caller's context so ownership follows the caller without stacking proxy layers. Throws if a factory is already registered. Returns the disposer; on dispose the factory slot is cleared.",
          "parameters": [
            {
              "name": "factory",
              "description": "the loop-owned factory {@link create}/{@link resume} delegate to."
            }
          ],
          "returns": "the disposer that clears the factory slot. The exact Cordis effect disposer (single-shot): composite (generator) effects may yield it directly — exact identity nests the teardown in order."
        },
        {
          "signature": "async create(options: CreateAgentOptions): Promise<AgentHandle>",
          "description": "Create and publish a new agent through the registered factory. Distinct from register (which records an already-constructed agent): this constructs the agent and its session. Rejects if no factory is registered or creation/setup fails. The resolved AgentHandle lets the owner tear down exactly this agent.",
          "parameters": [
            {
              "name": "options",
              "description": "shared identity, optional live parent, session seed/metadata, and agent options."
            }
          ],
          "returns": "the handle after setup, rollback-covered publication, and loop start complete."
        },
        {
          "signature": "async resume(options: ResumeAgentOptions): Promise<AgentHandle>",
          "description": "Load a persisted session and resume an agent on it through the registered factory. Rejects if no factory is registered; the factory rejects if session persistence is not configured or persistence/setup fails.",
          "parameters": [
            {
              "name": "options",
              "description": "persisted identity, optional live parent, configuration, and setup."
            }
          ],
          "returns": "the handle after setup, rollback-covered publication, and loop start complete."
        },
        {
          "signature": "register(agent: Agent): ReturnType<Context['effect']>",
          "description": "Register a live agent with source `startup`. Rejects if the id is already registered or a serial `agent/created` listener fails. Emits `agent/disposed` when the calling fiber is disposed — both with the agent's scope carrier (`scopeTarget(agent, agent)`): the subject is the agent in hand, so the emits are scope-filtered regardless of which context invoked `register` (calling through `agent.ctx` scopes EFFECTS; dispatch scoping always requires passing the carrier). The entry is a runtime root; factory-backed creation uses `options.parentAgent` for child ownership. Await the registration before using the agent.",
          "parameters": [
            {
              "name": "agent",
              "description": "the already-constructed agent to record in the store."
            }
          ],
          "returns": "the awaitable Cordis effect disposer (single-shot; a repeat call returns undefined without awaiting an in-flight teardown). Exact identity is load-bearing: a composite (generator) effect that owns a teardown ORDER — the agent factory's lifecycle chain — must yield THIS function so Cordis nests the unregistration at that yield position; yielding a wrapper would leave it disposing as a concurrent sibling on owner unload, unregistering the agent (and emitting `agent/disposed`) while its final turn is still draining."
        },
        {
          "signature": "enter(agent: Agent, owner: Agent | undefined): () => void",
          "description": "Insert an already-constructed agent without announcing it. This is the advanced ordered-lifecycle primitive used by the async agent factory: it first completes setup while the agent is unpublished, then assigns the returned detach closure into its pre-installed composite teardown before calling announce. Ordinary callers use register.",
          "parameters": [
            {
              "name": "agent",
              "description": "the prepared, unpublished agent."
            },
            {
              "name": "owner",
              "description": "explicitly supplied live runtime owner, or undefined for a top-level runtime root. This is runtime ownership, not the resumed session's durable parent lineage."
            }
          ],
          "returns": "an idempotent closure that removes this exact entry and emits `agent/disposed` with listener failures contained. When called from a `agent/created` listener, removal and disposal wait until the serial creation dispatch settles."
